import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for masked cumulative sum
masked_cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void masked_cumsum_kernel(const float* x, const bool* mask, float* out, int dim_size, int stride, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        int dim_idx = idx / stride % dim_size;
        int prev_idx = idx - dim_idx * stride;
        float sum = 0.0f;
        for (int i = 0; i <= dim_idx; ++i) {
            if (mask[prev_idx + i * stride]) {
                sum += x[prev_idx + i * stride];
            }
        }
        out[idx] = sum;
    }
}

torch::Tensor masked_cumsum_cuda(torch::Tensor x, torch::Tensor mask, int dim) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    int dim_size = x.size(dim);
    int stride = x.stride(dim);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    masked_cumsum_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), mask.data_ptr<bool>(), out.data_ptr<float>(), dim_size, stride, size);

    return out;
}
"""

masked_cumsum_cpp_source = (
    "torch::Tensor masked_cumsum_cuda(torch::Tensor x, torch::Tensor mask, int dim);"
)

# Compile the inline CUDA code for masked cumulative sum
masked_cumsum = load_inline(
    name="masked_cumsum",
    cpp_sources=masked_cumsum_cpp_source,
    cuda_sources=masked_cumsum_source,
    functions=["masked_cumsum_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    A model that performs a masked cumulative sum using a custom CUDA kernel.

    Parameters:
        dim (int): The dimension along which to perform the masked cumulative sum.
    """

    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.masked_cumsum = masked_cumsum

    def forward(self, x, mask):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, *input_shape).
            mask (torch.Tensor): Boolean mask of the same shape as x.

        Returns:
            torch.Tensor: Cumulative sum of elements where mask is True.
        """
        return self.masked_cumsum.masked_cumsum_cuda(x, mask, self.dim)
